/* Exact instructional diagrams. Node labels and costs match the question bank. */
const Diagrams = (() => {
 const blue='#2f6862', ink='#293630', gray='#596c61', green='#326947';
 const txt=(x,y,t,size=13,color=ink,weight=500)=>`<text x="${x}" y="${y}" text-anchor="middle" fill="${color}" font-size="${size}" font-weight="${weight}">${t}</text>`;
 const line=(x1,y1,x2,y2,color=gray,dash='')=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${color}" stroke-width="2.5" ${dash?`stroke-dasharray="${dash}"`:''}/>`;
 const box=(x,y,name,sub='',type='switch')=>`<g>${type==='router'?`<ellipse cx="${x}" cy="${y+4}" rx="39" ry="23" fill="#25534f"/><rect x="${x-39}" y="${y-8}" width="78" height="13" fill="#25534f"/><ellipse cx="${x}" cy="${y-8}" rx="39" ry="18" fill="${blue}"/><path d="M${x-20} ${y-8}h40m-20-9v18m-20-9 5-4m-5 4 5 4m35-4-5-4m5 4-5 4" fill="none" stroke="white" stroke-width="1.8"/>`:type==='pc'?`<rect x="${x-26}" y="${y-21}" width="52" height="34" rx="4" fill="#fff" stroke="${ink}" stroke-width="2"/><path d="M${x} ${y+13}v10m-15 0h30" stroke="${ink}" stroke-width="2"/><rect x="${x-21}" y="${y-16}" width="42" height="23" rx="1" fill="#e3ede5"/>`:`<rect x="${x-43}" y="${y-19}" width="86" height="36" rx="6" fill="${blue}"/>${[-28,-14,0,14,28].map(v=>`<rect x="${x+v-4}" y="${y-3}" width="8" height="7" rx="1" fill="#fff"/>`).join('')}`} ${txt(x,y+43,name,14,ink,700)}${sub?txt(x,y+62,sub,11,gray):''}</g>`;
 const svg=(body,label,h=300)=>`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 680 ${h}" role="img" aria-label="${label}"><title>${label}</title>${body}</svg>`;
 function hero(){return svg(`${line(340,65,175,145)}${line(340,65,505,145)}${line(175,145,85,230)}${line(175,145,260,230)}${line(505,145,420,230)}${line(505,145,595,230)}${box(340,65,'','','router')}${box(175,145,'','','router')}${box(505,145,'','','router')}${box(85,230,'','','pc')}${box(260,230,'','','switch')}${box(420,230,'','','switch')}${box(595,230,'','','pc')}`,'ภาพเครือข่ายเชื่อม Router, Switch และคอมพิวเตอร์',290)}
 const diagrams={
 switch:()=>svg(`${line(340,72,130,205)}${line(340,72,340,205)}${line(340,72,550,205)}${box(340,72,'SW1','MAC table แยกตาม VLAN')}${box(130,205,'PC A','MAC …AA · VLAN 10','pc')}${box(340,205,'PC B','MAC …BB · VLAN 10','pc')}${box(550,205,'PC C','MAC …CC · VLAN 20','pc')}${txt(190,135,'Fa0/1',11,blue)}${txt(372,155,'Fa0/2',11,blue)}${txt(489,135,'Fa0/3',11,blue)}`,'SW1 ต่อ PC A Fa0/1 และ PC B Fa0/2 ใน VLAN10 ส่วน PC C Fa0/3 อยู่ VLAN20',295),
 vlan:()=>svg(`<rect x="35" y="185" width="260" height="106" rx="10" fill="#e3ede5"/><rect x="385" y="185" width="260" height="106" rx="10" fill="#e3ede5"/>${line(185,70,495,70,blue)}${txt(340,42,'802.1Q TRUNK',13,blue,700)}${txt(340,98,'Allowed 10,20 · Native 999',11,gray)}${line(185,82,100,205)}${line(185,82,240,205)}${line(495,82,440,205)}${line(495,82,580,205)}${box(185,70,'SW1')}${box(495,70,'SW2')}${box(100,215,'VLAN 10','','pc')}${box(240,215,'VLAN 20','','pc')}${box(440,215,'VLAN 10','','pc')}${box(580,215,'VLAN 20','','pc')}`,'SW1 และ SW2 เชื่อม trunk ขนส่ง VLAN10/20 ตั้ง native VLAN999 ตรงกัน',310),
 stp:(state='normal')=>svg(`${line(340,65,150,220,green)}${line(340,65,530,220,state==='fail'?'#a0443b':green,state==='fail'?'6 5':'')}${line(150,220,530,220,state==='fail'?green:gray,state==='fail'?'':'7 5')}${txt(206,132,'cost 4',12,gray)}${txt(474,132,'cost 4',12,gray)}${txt(340,247,'cost 4',12,gray)}${box(340,65,'S1 · priority 24576','Root Bridge')}${box(150,220,'S2 · priority 32768','MAC …02')}${box(530,220,'S3 · priority 32768','MAC …03')}${state==='fail'?txt(475,171,'ลิงก์ล่ม',12,'#a0443b',700):`<path d="M474 210l18 20m0-20-18 20" stroke="#a0443b" stroke-width="4"/>${txt(482,194,'blocked',11,'#a0443b')}`}`,'STP สามสวิตช์ S1 priority24576 S2และS3 priority32768 MACของS2ต่ำกว่าS3 ทุกลิงก์cost4',315),
 intervlan:()=>svg(`<rect x="28" y="174" width="238" height="135" rx="12" fill="#e3ede5"/><rect x="414" y="174" width="238" height="135" rx="12" fill="#edf0dc"/>${line(340,53,340,163,blue)}${txt(469,76,'Trunk 802.1Q',12,blue)}${txt(487,98,'G0/0.10 → 192.168.10.1',11,gray)}${txt(487,119,'G0/0.20 → 192.168.20.1',11,gray)}${line(340,163,145,224)}${line(340,163,535,224)}${box(340,48,'R1','','router')}${box(340,158,'SW1')}${box(145,222,'PC 192.168.10.10','VLAN 10 · Gateway 192.168.10.1','pc')}${box(535,222,'PC 192.168.20.20','VLAN 20 · Gateway 192.168.20.1','pc')}`,'Router-on-a-Stick: VLAN10 192.168.10.0/24 และ VLAN20 192.168.20.0/24 ใช้ subinterface gateway .1',330),
 routing:()=>svg(`${line(135,190,340,70,green)}${line(340,70,545,190,green)}${line(135,190,545,190,gray,'7 5')}${txt(220,106,'cost 10',12,green)}${txt(464,106,'cost 10',12,green)}${txt(340,218,'cost 30',12,gray)}${box(135,190,'R1','','router')}${box(340,70,'R2','','router')}${box(545,190,'R3','','router')}${txt(340,281,'R1 → R2 → R3: รวม cost 20',14,green,600)}`,'OSPF topology R1-R2 cost10 R2-R3 cost10 R1-R3 cost30 เส้นทางผ่าน R2 มี cost20',310),
 gateway:(state='normal')=>svg(`${line(340,235,180,90,state==='fail'?'#a0443b':green,state==='fail'?'6 5':'')}${line(340,235,500,90,state==='fail'?green:gray,state==='fail'?'':'6 5')}<rect x="230" y="143" width="220" height="40" rx="8" fill="#e3ede5" stroke="#b5ccba"/>${txt(340,169,'Virtual IP 192.168.10.1',14,blue,700)}${box(180,70,'R1 · priority 110','192.168.10.2','router')}${box(500,70,'R2 · priority 100','192.168.10.3','router')}${txt(180,25,state==='fail'?'DOWN':'ACTIVE',12,state==='fail'?'#a0443b':green,700)}${txt(500,25,state==='fail'?'ACTIVE':'STANDBY',12,state==='fail'?green:gray,700)}${box(340,235,'Client 192.168.10.10','Default gateway ยังเป็น 192.168.10.1','pc')}`,'HSRP client192.168.10.10 ใช้VIP192.168.10.1 R1 real.2 priority110 R2 real.3 priority100',320),
 auth:()=>svg(`${line(110,125,340,125,blue)}${line(340,125,570,125,green)}${txt(225,104,'EAPOL',13,blue,700)}${txt(455,104,'RADIUS',13,green,700)}${box(110,125,'Supplicant','อุปกรณ์ผู้ใช้','pc')}${box(340,125,'Authenticator','สวิตช์ / Access Point')}${box(570,125,'Authentication','Server · RADIUS','router')}${txt(340,250,'ยืนยันตัวตนผ่าน → เปิดให้รับส่งข้อมูลตามนโยบาย',13,ink)}`,'802.1X ผู้ใช้ส่งEAPOLไปสวิตช์ สวิตช์ติดต่อAuthentication Serverผ่านRADIUS',285),
 wan:(state='normal')=>svg(`${line(340,70,120,225,blue)}${line(340,70,340,225,blue)}${line(340,70,560,225,blue)}${state==='mesh'?line(120,225,340,225,green):''}${state==='full'?`${line(120,225,340,225,green)}${line(340,225,560,225,green)}${'<path d="M120 232 Q340 348 560 232" fill="none" stroke="#326947" stroke-width="2.5"/>'}`:''}${box(340,65,'HQ','สำนักงานใหญ่','router')}${box(120,225,'Branch A','','router')}${box(340,225,'Branch B','','router')}${box(560,225,'Branch C','','router')}${txt(180,143,'WAN',11,gray)}${txt(497,143,'WAN',11,gray)}`,'เครือข่าย WAN HQ เชื่อมสาขา A B C แบบ hub-and-spoke เพิ่มลิงก์ A-B เป็น partial mesh',295)
 };
 const captions={switch:'เรียนรู้จาก Source MAC • ส่งต่อโดยดู Destination MAC • Flood ภายใน VLAN เท่านั้น',vlan:'Native VLAN 999 ไม่มีผู้ใช้ ส่วน VLAN 10/20 ถูกส่งแบบ tagged บน trunk ในตัวอย่างนี้',stp:'กรณีปกติ: S1 เป็น Root, S2/S3 ใช้ลิงก์ตรงไป S1; ลิงก์ S2–S3 ฝั่ง S3 ถูกบล็อก เพราะ Bridge ID ของ S2 ต่ำกว่า',intervlan:'ทุกเครื่องใช้ /24 และ Gateway .1 ของ VLAN ตัวเอง • Router ถอดและสร้าง Ethernet frame ใหม่เมื่อ route ข้าม VLAN',routing:'จำนวน hop น้อยกว่าไม่ได้แปลว่าดีกว่า: OSPF เปรียบเทียบผลรวม cost',gateway:'ตัวอย่าง HSRP: R1 เป็น Active เริ่มต้น • เปลี่ยนผู้ส่งต่อได้โดยไม่แก้ Default Gateway ที่ Client',auth:'802.1X แยกบทบาทผู้ขอเข้าใช้ ผู้ควบคุมพอร์ต และเซิร์ฟเวอร์ตรวจตัวตน',wan:'Hub-and-spoke: สาขาสื่อสารกันผ่าน HQ • ลิงก์เพิ่มเติมเปลี่ยนรูปแบบและจำนวนเส้นทาง'};
 function render(type,interactive=false){if(!diagrams[type])return '';return `<figure class="diagram" data-diagram="${type}"><div class="diagram-canvas">${diagrams[type]()}</div><figcaption>${captions[type]}</figcaption>${interactive&&['stp','gateway','wan'].includes(type)?`<div class="diagram-controls"><span>ลองเปลี่ยนสถานการณ์</span><button class="btn small" data-sim="normal">ปกติ</button>${type==='wan'?'<button class="btn small" data-sim="mesh">เพิ่มลิงก์ A–B</button><button class="btn small" data-sim="full">Full mesh</button>':`<button class="btn small" data-sim="fail">${type==='stp'?'ลิงก์ S1–S3 ล่ม':'R1 ล่ม'}</button>`}</div><div class="diagram-output" aria-live="polite"></div>`:''}</figure>`}
 function update(figure,state){const type=figure.dataset.diagram;figure.querySelector('.diagram-canvas').innerHTML=diagrams[type](state);const out=figure.querySelector('.diagram-output');out.textContent=state==='normal'?'กลับสู่สถานะเริ่มต้น':type==='stp'?'หลัง STP converge: S3 ใช้เส้นทาง S3 → S2 → S1 (cost 8) ลิงก์สำรองจึงกลับมา Forwarding — ภาพแสดงผลหลังคำนวณใหม่ ไม่ใช่เวลาจริง':type==='gateway'?'หลังตรวจพบว่า Active ล่มและ failover: R2 รับหน้าที่ Active แต่ Client ใช้ Virtual IP เดิม — ระยะเวลาจริงขึ้นกับ Timer และการตรวจจับ':state==='mesh'?'เพิ่มลิงก์ A–B รวม 4 ลิงก์: A ติดต่อ B ได้ตรง ส่วนสาขาคู่อื่นยังผ่าน HQ':'Full mesh 4 จุด ต้องมี 4×3÷2 = 6 ลิงก์: ทุกคู่มีลิงก์ตรง';figure.querySelectorAll('[data-sim]').forEach(b=>b.classList.toggle('primary',b.dataset.sim===state))}
 // Assessment figures contain givens only. Roles, selected paths and feedback
 // stay in the lesson figures so that the illustration does not answer a quiz.
 function question(type) {
   const neutral = {
     switch: () => diagrams.switch(),
     vlan: () => svg(line(170,85,510,85)+txt(340,61,'ลิงก์ระหว่างสวิตช์',13)+box(170,85,'SW1')+box(510,85,'SW2')+txt(170,179,'พอร์ตผู้ใช้ VLAN 10, 20',13)+txt(510,179,'พอร์ตผู้ใช้ VLAN 10, 20',13),'SW1 และ SW2 มีผู้ใช้ VLAN 10 และ VLAN 20 ทั้งสองฝั่ง',210),
     stp: () => svg(line(340,65,150,220)+line(340,65,530,220)+line(150,220,530,220)+txt(201,132,'cost 4',12)+txt(480,132,'cost 4',12)+txt(340,208,'cost 4',12)+box(340,65,'S1 · priority 24576')+box(150,220,'S2 · priority 32768','MAC …02')+box(530,220,'S3 · priority 32768','MAC …03'),'สวิตช์สามตัวเชื่อมเป็นสามเหลี่ยม ทุกลิงก์ cost 4',310),
     intervlan: () => diagrams.intervlan(),
     routing: () => svg(line(135,190,340,70)+line(340,70,545,190)+line(135,190,545,190)+txt(215,106,'cost 10',12)+txt(466,106,'cost 10',12)+txt(340,215,'cost 30',12)+box(135,190,'R1','','router')+box(340,70,'R2','','router')+box(545,190,'R3','','router'),'เส้นทางตรง R1–R3 cost 30 ส่วน R1–R2 และ R2–R3 มี cost 10 ต่อลิงก์',265),
     gateway: () => svg(line(340,220,180,65)+line(340,220,500,65)+box(180,65,'R1 · 192.168.10.2','priority 110','router')+box(500,65,'R2 · 192.168.10.3','priority 100','router')+txt(340,145,'Virtual IP 192.168.10.1',14,blue,700)+box(340,220,'Client 192.168.10.10','','pc'),'R1 และ R2 อยู่ในกลุ่ม HSRP เดียวกัน Virtual IP 192.168.10.1',285),
     auth: () => svg(line(105,112,340,112)+line(340,112,575,112)+txt(220,90,'EAPOL',13)+txt(457,90,'RADIUS',13)+box(105,112,'PC','','pc')+box(340,112,'Switch')+box(575,112,'Server','','pc'),'PC ต่อ Switch แล้ว Switch ติดต่อ RADIUS Server',195),
     wan: () => svg(line(340,65,120,215)+line(340,65,340,215)+line(340,65,560,215)+box(340,65,'HQ','','router')+box(120,215,'Branch A','','router')+box(340,215,'Branch B','','router')+box(560,215,'Branch C','','router'),'HQ มีลิงก์ไปยังแต่ละสาขา A B C',275)
   };
   return neutral[type] ? '<figure class="diagram"><div class="diagram-canvas">'+neutral[type]()+'</div><figcaption>แผนภาพประกอบโจทย์ · ใช้ค่าที่ระบุในคำถามหากมีการเปลี่ยนสถานการณ์</figcaption></figure>' : '';
 }
 return {render,hero,update,question};
})();
